        long long power = 1;
        while (exp > 0) {
            if (exp & 1) {
                power = (power * base_mod) % MODULO;
            }
            base_mod = (base_mod * base_mod) % MODULO;
            exp >>= 1;
        }
        cout << power << "\n";
